import{_ as l,l as o,o as e,c as n,v as r,p as s,x as t,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"证书透明 CT","description":"","frontmatter":{"title":"证书透明 CT","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/certificate-transparency.md","filePath":"cs/certificate-transparency.md","lastUpdated":1789023840000}'),h={name:"cs/certificate-transparency.md"};function C(T,a,_,A,E,m){const i=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="证书透明-ct" tabindex="-1">证书透明 CT <a class="header-anchor" href="#证书透明-ct" aria-label="Permalink to &quot;证书透明 CT&quot;">​</a></h1><div class="epigraph"><p>验证告诉你「这条链在数学上连到锚」；透明日志告诉你「这张证书曾经被公开过」。误签与流氓中间要在公众视野里被发现，而不是只在受害主机的缓存里。</p><footer>—— RFC 6962；Laurie, Certificate Transparency, CACM；对照 Merkle 树课</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/tls-cert-chain-validation">链验证</a>保证路径到锚。缺口是<strong>锚或中间被骗签了一张不该存在的证</strong>：验证仍通过。CT 用可公开审计的 Merkle 日志钉「签发事件」。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CA 会误签。浏览器要求叶证书带 SCT，证明已提交日志。包含证明走<a href="/cs/commitment-merkle-tree">Merkle</a>路径；监控者看域名。缺口是「可发现」不是「不能签发」——CT 是威慑与事后，不是吊销本身。</p><h3 id="日志也会撒谎" tabindex="-1">日志也会撒谎 <a class="header-anchor" href="#日志也会撒谎" aria-label="Permalink to &quot;日志也会撒谎&quot;">​</a></h3><p>多日志、八卦协议削弱单日志作弊。客户端抽查包含证明，不把日志当新的根 CA。</p><p><span class="marginnote">RFC 6962 / 9162。Google 的 CT 政策推动了部署。本课不写如何向日志灌垃圾的操作。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：CA 预提交→日志返回 SCT→握手带 SCT→客户端可验包含。对照 OCSP：吊销是「这张已作废」；CT 是「这张曾出现」。二者一起才接近生命周期。</p>',12)),(e(),s(p,null,{default:t(()=>[d(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20CA%5B%22CA%20%E7%AD%BE%E5%8F%91%22%5D%20--%3E%20LOG%5B%22CT%20%E6%97%A5%E5%BF%97%20Merkle%22%5D%0A%20%20LOG%20--%3E%20SCT%5B%22SCT%22%5D%0A%20%20SCT%20--%3E%20TLS%5B%22%E6%8F%A1%E6%89%8B%E6%90%BA%E5%B8%A6%22%5D%0A%20%20LOG%20--%3E%20MON%5B%22%E5%9F%9F%E5%90%8D%E7%9B%91%E6%8E%A7%E5%8F%91%E7%8E%B0%E8%AF%AF%E7%AD%BE%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>公钥基础设施的社会层：透明让错误可被点名。它不替代名字约束，不替代 ACME 对域名控制权的证明。下一课 ACME：自动化申请如何证明「我控制该名」。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把所有日志操作者列成名单。ACME 下一课从人工 CSR 换成自动化挑战。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>链验证通过仍可能是误签；CT 让签发可审计。</li><li>SCT + Merkle 包含；监控看自己的名。</li><li>发现 ≠ 吊销；OCSP/CRL 仍要。</li><li>下一课 ACME：自动证明域名控制。</li><li>出处：RFC 6962；Laurie, CACM；Merkle, 1980。</li></ul>',8))])}const S=l(h,[["render",C]]);export{u as __pageData,S as default};
